"""Retain full audit evidence, independently reverify, and return GPU custody."""
import datetime,fcntl,gzip,hashlib,json,shutil,subprocess
from pathlib import Path
import psutil
from verify_integrated_gate_bytes_astra_nov3 import verify_bytes
H=Path(__file__).resolve().parent;ROOT=H.parents[1]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(name,x):(H/name).write_text(json.dumps(x,indent=2)+'\n')
def main():
 p=H/'integrated-gate-bytes-frozen-plan-nov3.json';plan=json.loads(p.read_text());state=json.loads((H/'live-nov3-integrated-gate-bytes-custody.json').read_text());freebefore=shutil.disk_usage(H).free
 bad=[n for n,v in plan['file_pins'].items() if not (ROOT/n).is_file() or sha(ROOT/n)!=v];assert not bad
 assert sha(p)==state['manifest_sha256'];assert state['status']=='complete' and len(state['runs'])==2 and not state['owned_descendants_remaining']
 assert all(q['workflow_success'] and q['byte_receipt']['qualified'] and q['exit_code']==0 and not q['owned_descendants_remaining'] for q in state['runs'])
 assert not psutil.pid_exists(state['supervisor_pid']);assert all(not psutil.pid_exists(q['runner_pid']) for q in state['runs'])
 gpu=subprocess.check_output(['nvidia-smi','--query-compute-apps=pid,process_name','--format=csv,noheader'],text=True).strip();assert not gpu
 with open('/tmp/vllm-semantic-cache-gpu.lock','a') as f:fcntl.flock(f,fcntl.LOCK_EX|fcntl.LOCK_NB);fcntl.flock(f,fcntl.LOCK_UN)
 compression=[];receipts={};files=[];details={}
 for item in plan['execution_order']:
  d=H/'runs'/item['name'];rp=d/'raw.json.gz';raw=json.load(gzip.open(rp,'rt'));assert raw['owned_descendants_remaining']==[] and raw['performance_eligible'] is False
  for f in d.glob('byte-audit-*.jsonl'):
   original=sha(f);n=f.stat().st_size;dst=f.with_suffix(f.suffix+'.gz');assert not dst.exists()
   with f.open('rb') as a,gzip.open(dst,'wb',compresslevel=3) as b:shutil.copyfileobj(a,b)
   with gzip.open(dst,'rb') as g:assert hashlib.file_digest(g,'sha256').hexdigest()==original
   compression.append({'original_path':str(f.relative_to(ROOT)),'original_sha256':original,'original_bytes':n,'compressed_path':str(dst.relative_to(ROOT)),'compressed_sha256':sha(dst),'compressed_bytes':dst.stat().st_size,'lossless_verified':True});f.unlink()
  r=verify_bytes(rp);assert r['qualified'],r['issues']
  for group,pins in r['pins'].items():
   if group not in ['source_pins','runtime_pins','pins','harness_pins','artifact_pins']:continue
   base=ROOT/raw['args']['source_dir'] if group=='source_pins' else ROOT if group=='harness_pins' else H
   for key,value in pins.items():assert sha(base/key)==value,(item['name'],group,key)
  receipt=H/(item['name']+'-qualification.json');before=receipt.with_name(receipt.stem+'-precompression.json');assert not before.exists();before.write_bytes(receipt.read_bytes());receipt.write_text(json.dumps(r,indent=2)+'\n');receipts[item['arm']]=str(receipt.relative_to(ROOT));details[item['arm']]=r;files.extend(f for f in d.rglob('*') if f.is_file())
 files.extend(ROOT/q['console']['path'] for q in state['runs'])
 write('live-nov3-integrated-gate-bytes-compression.json',compression)
 summary={'schema':'astra-integrated-gate-both-arm-byte-summary-v1','plan_sha256':sha(p),'qualified':True,'receipts':receipts,'natural_eos':sum(x['natural_eos'] for x in details.values()),'jobs_by_arm':{a:r['directions'] for a,r in details.items()},'bytes_by_arm':{a:r['bytes_by_direction'] for a,r in details.items()},'components_per_job':28,'total_component_observations':sum(r['component_observations'] for r in details.values()),'all_bytes_equal':True,'all_executed_one_byte_controls_rejected':True,'native_final_and_load_Prometheus_counts_and_bytes_reconciled':True,'both_directions_with_first_admission_restoration':True,'preemptions_by_arm':{a:r['preemptions'] for a,r in details.items()},'first_admission_attribution_by_arm':{a:r['first_admission_attribution'] for a,r in details.items()},'candidate_gate_activation':details['candidate']['gate_receipt']['per_hint'],'candidate_preservation_audit':details['candidate']['preservation_audit_configured'],'intrusive_byte_audit':True,'performance_eligible':False,'exact_geometry':{'gpu_blocks':1536,'cpu_blocks':2048,'active':8,'batch_tokens':1024,'hint_interval_ms':1000,'cudagraph':'FULL_DECODE_ONLY','compile_mode':0},'qualification_scope':'All28component copies checked at transfer completion for exercised TP1 dense FP16 AWQ jobs, including warmup; independent block/page geometry and observed native aggregate final/load counts/bytes reconcile. Native Transfer.num_bytes is not independently observed per job. No semantic boundary, future lifetime, answer quality, endurance or performance proof.','launch_status':'Await ROOT independent raw recomputation and separate manifest-bound launch gate. No fresh confirmation invoked.'}
 write('live-nov3-integrated-gate-bytes-independent-summary.json',summary)
 # Only generated bytecode for the new reviewer programs is disposable here.
 scratch=[]
 for name in ['supervise_integrated_gate_bytes_astra_nov3','verify_integrated_gate_bytes_astra_nov3','finalize_integrated_gate_bytes_astra_nov3']:
  for f in (H/'__pycache__').glob(name+'.*.pyc'):
   scratch.append({'path':str(f.relative_to(ROOT)),'bytes':f.stat().st_size});f.unlink()
 inv={'schema':'astra-integrated-gate-byte-handback-v1','created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'custody':'ASTRA -> ROOT','runs':2,'natural_eos':summary['natural_eos'],'pins_checked':len(plan['file_pins']),'pin_mismatches':bad,'supervisor_exited':True,'all_runner_processes_exited':True,'all_raw_descendant_lists_empty':True,'owned_processes_remaining':[],'gpu_compute_processes':gpu,'gpu_lock_available':True,'artifact_bytes_retained':sum(f.stat().st_size for f in files),'retained_files':[{'path':str(f.relative_to(ROOT)),'bytes':f.stat().st_size} for f in files],'compression':compression,'scratch_removed':scratch,'lossless_compression_bytes_saved':sum(q['original_bytes']-q['compressed_bytes'] for q in compression),'free_bytes_before_cleanup':freebefore,'free_bytes_after_cleanup':shutil.disk_usage(H).free,'retention_reason':'Full audit JSONL preserved in verified gzip, raw/server/driver logs and pin archives retained. Prior results/shared caches/fresh inputs unchanged. No disposable worktrees/downloads/checkpoints or owned processes remain. WSL free space only; concurrent activity may affect delta and Windows VHDX reclamation is not asserted.'}
 write('live-nov3-integrated-gate-bytes-handback-inventory.json',inv)
 print(json.dumps({k:summary[k] for k in ['qualified','natural_eos','jobs_by_arm','total_component_observations','preemptions_by_arm','candidate_gate_activation']}))
 print(json.dumps({'saved_bytes':inv['lossless_compression_bytes_saved'],'retained_bytes':inv['artifact_bytes_retained'],'gpu_idle':True,'custody':'ASTRA -> ROOT'}))
if __name__=='__main__':main()
